  return headers;
};
const validate = (headers, type) => {
  const directives = new Set((headers.get('cache-control') || '').toLowerCase().split(',').map(item => item.trim()));
  if (headers.get('content-type') !== type || !directives.has('no-store') || !directives.has('max-age=0') ||
      headers.get('x-content-type-options') !== 'nosniff' ||
      headers.get('x-winwidget-revision') !== process.env.EXPECTED_REVISION) process.exit(1);
};
validate(parse(process.env.IDENTITY_AVATAR_READY_HEADERS), 'application/json');
validate(parse(process.env.IDENTITY_AVATAR_READY_SIGNATURE_HEADERS), 'application/octet-stream');
