identity_avatar_install_runtime_stability_nginx_contract() {
	[[ $# -eq 0 && "$EXPECTED_REVISION" =~ ^[0-9a-f]{40}$ &&
		"$(uname -s)" == 'Linux' && "$(id -u)" == '0' ]] || return 1
	local template="$SERVER_ROOT/deploy/identity-avatar-client-ready-nginx.conf" rendered rendered_sha target_sha
