		! -L "$(dirname -- "$identity_avatar_client_ready_nginx_target")" ]] || return 1
	rendered="${identity_avatar_client_ready_nginx_target}.tmp.$$"
	identity_avatar_recover_publication_temps "$identity_avatar_client_ready_nginx_target" || return 1
	sed "s/__IDENTITY_AVATAR_SERVER_REVISION__/$EXPECTED_REVISION/g" "$template" >"$rendered" || return 1
	[[ "$(grep -Fc '__IDENTITY_AVATAR_SERVER_REVISION__' "$template")" == '8' &&
		"$(grep -Fc "$EXPECTED_REVISION" "$rendered")" == '8' ]] || return 1
	rendered_sha="$(identity_avatar_sha256 "$rendered")" || return 1
	if [[ -e "$identity_avatar_client_ready_nginx_target" || -L "$identity_avatar_client_ready_nginx_target" ]]; then
