		target_sha="$(identity_avatar_sha256 "$identity_avatar_client_ready_nginx_target")" || return 1
		if [[ "$target_sha" == "$rendered_sha" ]]; then
			rm -f -- "$rendered"
		else
			identity_avatar_durable_publish "$rendered" "$identity_avatar_client_ready_nginx_target" replace 644 || return 1
		fi
	else
		identity_avatar_durable_publish "$rendered" "$identity_avatar_client_ready_nginx_target" no-clobber 644 || return 1
	fi
	nginx -t >/dev/null 2>&1 || return 1
	systemctl reload nginx >/dev/null || return 1
}

identity_avatar_validate_client_trust_evidence() {
	[[ ($# -eq 1 || $# -eq 2) && "$1" =~ ^[0-9a-f]{64}$ &&
		("${2:-}" == '' || "${2:-}" =~ ^[0-9a-f]{64}$) ]] || return 1
	identity_avatar_validate_private_file "$identity_avatar_client_trust_evidence" || return 1
	identity_avatar_validate_private_file "$identity_avatar_client_signing_public_key" || return 1
	identity_avatar_validate_private_file "$identity_avatar_signing_public_key" || return 1
	local ownership_revision
	ownership_revision="$(identity_avatar_ownership_revision_context)" || return 1
	IDENTITY_AVATAR_CLIENT_TRUST_FILE="$identity_avatar_client_trust_evidence" \
	IDENTITY_AVATAR_CLIENT_TRUST_LIFECYCLE_PUBLIC_KEY="$identity_avatar_signing_public_key" \
	IDENTITY_AVATAR_CLIENT_TRUST_FRONTEND_PUBLIC_KEY="$identity_avatar_client_signing_public_key" \
	IDENTITY_AVATAR_CLIENT_TRUST_EXPECTED_SOURCE_SHA="$1" \
	IDENTITY_AVATAR_CLIENT_TRUST_EXPECTED_SOURCE_PATH_SHA="${2:-}" \
	EXPECTED_REVISION="$ownership_revision" node <<'NODE'
const { createHash, createPublicKey, verify } = require('node:crypto');
const { readFileSync } = require('node:fs');
let value;
try { value = JSON.parse(readFileSync(process.env.IDENTITY_AVATAR_CLIENT_TRUST_FILE, 'utf8')); }
catch { process.exit(1); }
const keys = ['version', 'kind', 'serverRevision', 'sourcePathSha256', 'sourcePublicKeySha256',
  'destinationPath', 'destinationPublicKeySha256', 'publicKeySpkiSha256', 'installedAt', 'signature'];
const { signature, ...payload } = value || {};
const publicBytes = readFileSync(process.env.IDENTITY_AVATAR_CLIENT_TRUST_FRONTEND_PUBLIC_KEY);
let key;
try { key = createPublicKey(publicBytes); } catch { process.exit(1); }
const fileSha = createHash('sha256').update(publicBytes).digest('hex');
const spkiSha = createHash('sha256').update(key.export({ type: 'spki', format: 'der' })).digest('hex');
if (JSON.stringify(Object.keys(value || {})) !== JSON.stringify(keys) ||
    value.version !== 1 || value.kind !== 'identity-avatar-client-trust-bootstrap' ||
    value.serverRevision !== process.env.EXPECTED_REVISION ||
    !/^[a-f0-9]{64}$/.test(value.sourcePathSha256 || '') ||
    (process.env.IDENTITY_AVATAR_CLIENT_TRUST_EXPECTED_SOURCE_PATH_SHA &&
      value.sourcePathSha256 !== process.env.IDENTITY_AVATAR_CLIENT_TRUST_EXPECTED_SOURCE_PATH_SHA) ||
    value.sourcePublicKeySha256 !== process.env.IDENTITY_AVATAR_CLIENT_TRUST_EXPECTED_SOURCE_SHA ||
    value.destinationPath !== '/opt/winwidget/deploy/backend/.identity-avatar-client-signing.public.pem' ||
    value.destinationPublicKeySha256 !== fileSha || value.sourcePublicKeySha256 !== fileSha ||
    value.publicKeySpkiSha256 !== spkiSha || key.asymmetricKeyType !== 'ed25519' ||
    !/^[0-9TZ:.-]+$/.test(value.installedAt || '') || typeof signature !== 'string' ||
    !verify(null, Buffer.from(JSON.stringify(payload)),
      readFileSync(process.env.IDENTITY_AVATAR_CLIENT_TRUST_LIFECYCLE_PUBLIC_KEY),
      Buffer.from(signature, 'base64'))) process.exit(1);
NODE
}

identity_avatar_install_client_public_key() (
	[[ $# -eq 1 && "$1" == /* && "$1" != "$identity_avatar_client_signing_public_key" ]] || return 1
	identity_avatar_require_production_inputs
	acquire_production_deploy_lock 'Identity avatar frontend public-key trust bootstrap'
	local source="$1" source_sha source_path_sha spki_sha data temporary ownership_revision
	ownership_revision="$(identity_avatar_ownership_revision_context)" || return 1
