	if [[ ! -e "$source" && ! -L "$source" ]]; then
		identity_avatar_validate_private_file "$identity_avatar_client_signing_public_key" ||
			identity_avatar_fail 'transfer is absent and no exact pinned frontend key exists' || return 1
		source_sha="$(identity_avatar_sha256 "$identity_avatar_client_signing_public_key")" || return 1
