	IDENTITY_AVATAR_CLIENT_TRUST_SOURCE="$source" node <<'NODE'
const { createPublicKey } = require('node:crypto');
const { readFileSync } = require('node:fs');
const text = readFileSync(process.env.IDENTITY_AVATAR_CLIENT_TRUST_SOURCE, 'utf8');
if (!/^-----BEGIN PUBLIC KEY-----\n(?:[A-Za-z0-9+/]{1,64}\n)+-----END PUBLIC KEY-----\n$/.test(text)) process.exit(1);
let key;
try { key = createPublicKey(text); } catch { process.exit(1); }
if (key.asymmetricKeyType !== 'ed25519') process.exit(1);
NODE
	source_sha="$(identity_avatar_sha256 "$source")" || return 1
	spki_sha="$(IDENTITY_AVATAR_CLIENT_TRUST_SOURCE="$source" node -e '
const {createHash,createPublicKey}=require("node:crypto");const {readFileSync}=require("node:fs");
const key=createPublicKey(readFileSync(process.env.IDENTITY_AVATAR_CLIENT_TRUST_SOURCE));
process.stdout.write(createHash("sha256").update(key.export({type:"spki",format:"der"})).digest("hex"));')" || return 1
	if [[ -e "$identity_avatar_client_signing_public_key" || -L "$identity_avatar_client_signing_public_key" ]]; then
		identity_avatar_validate_private_file "$identity_avatar_client_signing_public_key" || return 1
		[[ "$(identity_avatar_sha256 "$identity_avatar_client_signing_public_key")" == "$source_sha" ]] ||
			identity_avatar_fail 'pinned frontend public key already exists with a different fingerprint' || return 1
	else
		identity_avatar_recover_publication_temps "$identity_avatar_client_signing_public_key" || return 1
		temporary="${identity_avatar_client_signing_public_key}.tmp.$$"
