  value.releaseEvidenceSha256!==process.env.IDENTITY_AVATAR_IMAGE_ADOPTION_RELEASE||
  value.releaseEvidenceSignatureSha256!==process.env.IDENTITY_AVATAR_IMAGE_ADOPTION_RELEASE_SIGNATURE||
  value.releaseTreeSha256!==process.env.IDENTITY_AVATAR_IMAGE_ADOPTION_TREE||
