identity_avatar_runtime_stability_live_frontend_binding() {
	[[ $# -le 1 ]] || return 1
	identity_avatar_validate_marker || return 1
	local revision initial release_sha client_file probe adoption context chain terminal binding generation body signature
	revision="$(identity_avatar_marker_value current_client_revision)" || return 1
	initial="$(identity_avatar_marker_value client_revision)" || return 1
	if [[ "$revision" == "$initial" ]]; then
		client_file="$identity_avatar_client_evidence"
		release_sha="$(identity_avatar_json_string_field "$client_file" releaseEvidenceSha256)" || return 1
	else
		client_file="$identity_avatar_artifact_root/client-soak-retarget-recorded-$revision.json"
		release_sha="$(identity_avatar_json_string_field "$client_file" releaseEvidenceSha256)" || return 1
	fi
	probe="$(identity_avatar_verify_live_client_switch "$revision" "$release_sha")" || return 1
	if [[ $# -eq 1 ]]; then
		chain="$1"
	else
		chain="$(identity_avatar_validate_runtime_stability_chain bound)" || return 1
	fi
	terminal="$(IDENTITY_AVATAR_STABILITY_CHAIN="$chain" node -e '
const value=JSON.parse(process.env.IDENTITY_AVATAR_STABILITY_CHAIN);if(!value.terminal)process.exit(1);process.stdout.write(JSON.stringify(value.terminal));')" || return 1
	binding="$(IDENTITY_AVATAR_STABILITY_TERMINAL="$terminal" node -e '
const value=JSON.parse(process.env.IDENTITY_AVATAR_STABILITY_TERMINAL);process.stdout.write(JSON.stringify(value.frontendBinding));')" || return 1
	if [[ "$(IDENTITY_AVATAR_BINDING="$binding" node -e 'process.stdout.write(JSON.parse(process.env.IDENTITY_AVATAR_BINDING).bindingKind)')" != \
		'frontend-runtime-rebind' ]]; then
		adoption="$(identity_avatar_verify_frontend_image_adoption "$revision" "$release_sha" \
			"$(IDENTITY_AVATAR_PROBE="$probe" node -e 'process.stdout.write(JSON.parse(process.env.IDENTITY_AVATAR_PROBE).releaseEvidenceSignatureSha256)')" \
			"$(IDENTITY_AVATAR_PROBE="$probe" node -e 'process.stdout.write(JSON.parse(process.env.IDENTITY_AVATAR_PROBE).releaseTreeSha256)')" \
			"$(IDENTITY_AVATAR_PROBE="$probe" node -e 'process.stdout.write(JSON.parse(process.env.IDENTITY_AVATAR_PROBE).releaseFullManifestSha256)')")" || return 1
		IDENTITY_AVATAR_BINDING="$binding" IDENTITY_AVATAR_PROBE="$probe" IDENTITY_AVATAR_ADOPTION="$adoption" node <<'NODE'
const binding=JSON.parse(process.env.IDENTITY_AVATAR_BINDING),probe=JSON.parse(process.env.IDENTITY_AVATAR_PROBE),adoption=JSON.parse(process.env.IDENTITY_AVATAR_ADOPTION);
const expected={...binding,imageId:adoption.clientImageId,evidenceSha256:adoption.evidenceSha256,
  evidenceSignatureSha256:adoption.evidenceSignatureSha256,processStartedAt:probe.processStartedAt};
for(const [key,value] of Object.entries(expected))if(binding[key]!==value)process.exit(1);
process.stdout.write(JSON.stringify(binding));
