	trap 'temporary_cleanup="${temporary:-}"; trap - RETURN; [[ -z "$temporary_cleanup" ]] || rm -rf -- "$temporary_cleanup"' RETURN
	body="$temporary/adopted.json"; signature="$temporary/adopted.sig"
	identity_avatar_fetch_frontend_soak_file \
		"$IDENTITY_AVATAR_CLIENT_ORIGIN/.well-known/winwidget/identity-avatar-client/$revision/runtime-rebind/generation-$(printf '%06d' "$generation")/adopted-v1.json" \
		"$body" 65536 || return 1
	identity_avatar_fetch_frontend_soak_file \
		"$IDENTITY_AVATAR_CLIENT_ORIGIN/.well-known/winwidget/identity-avatar-client/$revision/runtime-rebind/generation-$(printf '%06d' "$generation")/adopted-v1.json.sig" \
		"$signature" 1024 || return 1
	IDENTITY_AVATAR_BINDING="$binding" IDENTITY_AVATAR_PROBE="$probe" IDENTITY_AVATAR_ADOPTED_BODY="$body" \
	IDENTITY_AVATAR_ADOPTED_SIGNATURE="$signature" IDENTITY_AVATAR_FRONTEND_KEY="$identity_avatar_client_signing_public_key" node <<'NODE'
const {createHash,verify}=require('node:crypto');const {readFileSync}=require('node:fs');
const binding=JSON.parse(process.env.IDENTITY_AVATAR_BINDING),probe=JSON.parse(process.env.IDENTITY_AVATAR_PROBE);
