identity_avatar_validate_client_retarget_outcome_window() {
	[[ $# -eq 2 && "$1" =~ ^(fresh|historical)$ &&
		"$2" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$ &&
		("${IDENTITY_AVATAR_TEST_NOW_MS:-}" == '' ||
