	IDENTITY_AVATAR_CLIENT_RETARGET_WINDOW_AT="$2" \
	IDENTITY_AVATAR_CLIENT_RETARGET_WINDOW_NOW_MS="${IDENTITY_AVATAR_TEST_NOW_MS:-}" node <<'NODE'
const mode = process.env.IDENTITY_AVATAR_CLIENT_RETARGET_WINDOW_MODE;
