  ? Number(process.env.IDENTITY_AVATAR_CLIENT_RETARGET_WINDOW_NOW_MS) : Date.now();
if (!Number.isSafeInteger(now) || !Number.isFinite(at) || now - at < -120000 ||
    (mode === 'fresh' && now - at > 1800000)) process.exit(1);
