	IDENTITY_AVATAR_CLIENT_RETARGET_REFERENCE_AT="$2" node <<'NODE'
const recorded = Date.parse(process.env.IDENTITY_AVATAR_CLIENT_RETARGET_RECORDED_AT);
const reference = Date.parse(process.env.IDENTITY_AVATAR_CLIENT_RETARGET_REFERENCE_AT);
if (!Number.isFinite(recorded) || !Number.isFinite(reference) ||
    recorded < reference || recorded - reference > 120000) process.exit(1);
NODE
}

identity_avatar_validate_client_retarget_prepared_journal() {
	[[ $# -eq 12 && "$1" =~ ^[0-9a-f]{40}$ && "$2" =~ ^[0-9a-f]{64}$ &&
		"$3" =~ ^[0-9a-f]{64}$ && "$4" =~ ^[0-9a-f]{64}$ && "$5" =~ ^[0-9a-f]{40}$ &&
		"$6" =~ ^[0-9a-f]{40}$ && "$7" =~ ^[0-9a-f]{40}$ && "$8" =~ ^[0-9a-f]{40}$ &&
		"$9" =~ ^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$ &&
		"${10}" =~ ^(pending|[0-9a-f]{64})$ && "${11}" =~ ^(first|[0-9a-f]{64})$ &&
		"${12}" =~ ^[1-4]$ ]] || return 1
	local target="$1" journal outcome outcome_signature heartbeat heartbeat_signature
	journal="$identity_avatar_artifact_root/client-soak-retarget-prepared-$target.json"
	outcome="$identity_avatar_artifact_root/frontend-client-soak-retarget-$target.json"
	outcome_signature="${outcome}.sig"
	heartbeat="$identity_avatar_artifact_root/frontend-client-soak-retarget-$target-heartbeat-000001.json"
	heartbeat_signature="${heartbeat}.sig"
	identity_avatar_verify_detached_lifecycle_evidence "$journal" \
		identity-avatar-client-soak-retarget-prepared || return 1
	for file in "$outcome" "$outcome_signature" "$heartbeat" "$heartbeat_signature" \
		"$identity_avatar_client_signing_public_key"; do
		identity_avatar_validate_private_file "$file" || return 1
	done
	IDENTITY_AVATAR_CLIENT_RETARGET_PREPARED_FILE="$journal" \
	IDENTITY_AVATAR_CLIENT_RETARGET_PREPARED_OUTCOME="$outcome" \
	IDENTITY_AVATAR_CLIENT_RETARGET_PREPARED_OUTCOME_SIGNATURE="$outcome_signature" \
	IDENTITY_AVATAR_CLIENT_RETARGET_PREPARED_HEARTBEAT="$heartbeat" \
	IDENTITY_AVATAR_CLIENT_RETARGET_PREPARED_HEARTBEAT_SIGNATURE="$heartbeat_signature" \
	IDENTITY_AVATAR_CLIENT_RETARGET_PREPARED_FRONTEND_KEY="$identity_avatar_client_signing_public_key" \
	IDENTITY_AVATAR_CLIENT_RETARGET_PREPARED_TARGET="$1" \
	IDENTITY_AVATAR_CLIENT_RETARGET_PREPARED_RELEASE_SHA="$2" \
	IDENTITY_AVATAR_CLIENT_RETARGET_PREPARED_BODY_SHA="$3" \
	IDENTITY_AVATAR_CLIENT_RETARGET_PREPARED_SIGNATURE_SHA="$4" \
	IDENTITY_AVATAR_CLIENT_RETARGET_PREPARED_INITIAL="$5" \
	IDENTITY_AVATAR_CLIENT_RETARGET_PREPARED_PREVIOUS="$6" \
	IDENTITY_AVATAR_CLIENT_RETARGET_PREPARED_OWNER="$7" \
	IDENTITY_AVATAR_CLIENT_RETARGET_PREPARED_RUNTIME="$8" \
