		IDENTITY_AVATAR_REVOCATION_SHA="${12}" IDENTITY_AVATAR_SMOKE_SHA="${13}" \
		IDENTITY_AVATAR_BOUNDARY_AT="${14}" IDENTITY_AVATAR_RESET_ANCHOR_SHA="${15}" \
		IDENTITY_AVATAR_STABILITY_GENERATION="${16}" IDENTITY_AVATAR_STABILITY_SHA="${17}" \
	IDENTITY_AVATAR_HEARTBEAT_WRITER_FILE="$identity_avatar_writer_fence_evidence" \
	IDENTITY_AVATAR_HEARTBEAT_POLICY_FILE="$identity_avatar_policy_evidence" \
	IDENTITY_AVATAR_HEARTBEAT_SMOKE_FILE="$identity_avatar_authenticated_smoke_evidence" node <<'NODE'
const { createHash, verify } = require('node:crypto');
