const exactKeys = (value, keys) => JSON.stringify(Object.keys(value || {})) === JSON.stringify(keys);
const decimal = value => typeof value === 'string' && /^(0|[1-9][0-9]*)$/.test(value);
let writer;
let policy;
let smoke;
try {
  writer = JSON.parse(readFileSync(process.env.IDENTITY_AVATAR_HEARTBEAT_WRITER_FILE));
  policy = JSON.parse(readFileSync(process.env.IDENTITY_AVATAR_HEARTBEAT_POLICY_FILE));
  smoke = JSON.parse(readFileSync(process.env.IDENTITY_AVATAR_HEARTBEAT_SMOKE_FILE));
} catch { fail(); }
const expectedRuntime = {
