};
	let previousSha = process.env.IDENTITY_AVATAR_RESET_ANCHOR_SHA;
let previousAt = Date.parse(process.env.IDENTITY_AVATAR_BOUNDARY_AT);
let previousFrontendSequence = 0;
let previousFrontendSha = '';
let previousFrontendSignatureSha = '';
let previousFrontendEnded = null;
let firstFrontendStarted = null;
let previousBackendFiles = [];
let previousBackendConfigurationSha = '';
let lastBackendLogSetSha = '';
let lastBackendEnded = null;
let firstAt = null;
let firstSha = null;
let lastSha = null;
let maxGapSeconds = 0;
if (!Number.isFinite(previousAt)) fail();
for (let index = 0; index < names.length; index += 1) {
  if (names[index] !== `heartbeat-${String(index + 1).padStart(6, '0')}.json`) fail();
  const heartbeatPath = join(process.env.IDENTITY_AVATAR_HEARTBEAT_ROOT, names[index]);
  const metadata = lstatSync(heartbeatPath);
  if (!metadata.isFile() || metadata.isSymbolicLink() || metadata.nlink !== 1 ||
      (process.platform === 'linux' && (metadata.uid !== 0 || metadata.gid !== 0 ||
       (metadata.mode & 0o777) !== 0o600))) fail();
  const bytes = readFileSync(heartbeatPath);
  let value;
  try { value = JSON.parse(bytes); } catch { fail(); }
  if (!exactKeys(value, expectedKeys)) fail();
  const { signature, ...payload } = value;
  const exact = [
    ['serverRevision', process.env.IDENTITY_AVATAR_OWNERSHIP_REVISION],
    ['currentRuntimeRevision', process.env.EXPECTED_REVISION],
	    ['clientRevision', process.env.IDENTITY_AVATAR_CLIENT_REVISION],
	    ['runtimeStabilityGeneration', Number(process.env.IDENTITY_AVATAR_STABILITY_GENERATION)],
	    ['runtimeStabilityEvidenceSha256', process.env.IDENTITY_AVATAR_STABILITY_SHA],
    ['previousEvidenceSha256', previousSha],
	    ['clientEvidenceSha256', process.env.IDENTITY_AVATAR_CLIENT_SHA],
	    ['clientRetargetEvidenceSha256', process.env.IDENTITY_AVATAR_CLIENT_RETARGET_SHA],
	    ['runtimeRetargetEvidenceSha256', process.env.IDENTITY_AVATAR_RUNTIME_RETARGET_SHA],
    ['writerFenceEvidenceSha256', process.env.IDENTITY_AVATAR_WRITER_SHA],
    ['storagePolicyEvidenceSha256', process.env.IDENTITY_AVATAR_POLICY_SHA],
    ['inventoryManifestSha256', process.env.IDENTITY_AVATAR_INVENTORY_SHA],
    ['statusManifestSha256', process.env.IDENTITY_AVATAR_STATUS_SHA],
    ['revocationEvidenceSha256', process.env.IDENTITY_AVATAR_REVOCATION_SHA],
    ['authenticatedSmokeEvidenceSha256', process.env.IDENTITY_AVATAR_SMOKE_SHA],
    ['ownershipRevision', process.env.IDENTITY_AVATAR_OWNERSHIP_REVISION],
    ['ownershipInventorySha256', process.env.IDENTITY_AVATAR_INVENTORY_SHA],
    ['ownershipStatusSha256', process.env.IDENTITY_AVATAR_STATUS_SHA],
      ['clientLiveRevision', process.env.IDENTITY_AVATAR_CLIENT_REVISION],
      ['clientProcessStartedAt', process.env.IDENTITY_AVATAR_CLIENT_PROCESS_STARTED_AT],
      ['clientReleaseEvidenceSha256', process.env.IDENTITY_AVATAR_CLIENT_RELEASE_SHA],
      ['clientReleaseEvidenceSignatureSha256', process.env.IDENTITY_AVATAR_CLIENT_RELEASE_SIGNATURE_SHA],
      ['bucketVersioningStatus', policy.bucketVersioningStatus],
  ];
  if (value.version !== 1 || value.kind !== 'identity-avatar-soak-heartbeat' ||
      value.sequence !== index + 1 || exact.some(([key, expected]) => value[key] !== expected) ||
      value.ownershipPhase !== 'ACTIVE' || value.cleanupBlocked !== 0 ||
      value.cleanupExpiredProcessing !== 0 ||
      Object.entries(expectedRuntime).some(([key, expected]) =>
        !exactKeys(value[key], runtimeKeys) || JSON.stringify(value[key]) !== JSON.stringify(expected)) ||
      !exactKeys(value.frontendLogEvidence, frontendKeys) ||
      !exactKeys(value.backendLogEvidence, backendKeys) ||
      typeof signature !== 'string' || !verify(null, Buffer.from(JSON.stringify(payload)),
        readFileSync(process.env.IDENTITY_AVATAR_HEARTBEAT_PUBLIC_KEY),
        Buffer.from(signature, 'base64'))) fail();
  const frontend = value.frontendLogEvidence;
  const backend = value.backendLogEvidence;
  if (!Number.isSafeInteger(frontend.sequence) || frontend.sequence < 1 ||
      !/^[a-f0-9]{64}$/.test(frontend.evidenceSha256 || '') ||
      !/^[a-f0-9]{64}$/.test(frontend.evidenceSignatureSha256 || '') ||
      !/^[a-f0-9]{64}$/.test(frontend.logSetSha256 || '') ||
      !/^[a-f0-9]{64}$/.test(frontend.logConfigurationSha256 || '') ||
      frontend.apiV1FilesRequestCount !== 0 || frontend.uploadsSuccessfulGetHeadCount !== 0 ||
      !Number.isSafeInteger(frontend.uploadsGetHeadRequestCount) || frontend.uploadsGetHeadRequestCount < 0 ||
      (index === 0 && Date.parse(frontend.chainStartedAt) > previousAt) ||
      (firstFrontendStarted !== null && frontend.chainStartedAt !== firstFrontendStarted) ||
      (previousFrontendSequence > frontend.sequence) ||
      (previousFrontendSequence === frontend.sequence && previousFrontendSha !== frontend.evidenceSha256) ||
      (previousFrontendSequence < frontend.sequence && previousFrontendEnded !== null &&
       Date.parse(frontend.windowEndedAt) <= previousFrontendEnded)) fail();
  if (previousFrontendSequence === frontend.sequence && previousFrontendSignatureSha &&
      previousFrontendSignatureSha !== frontend.evidenceSignatureSha256) fail();
	  if (!Array.isArray(backend.logFiles) || backend.logFiles.length < 1 || backend.logFiles.length > 16 ||
      backend.host !== 'api.winwidget.ru' || backend.probeClass !== 'soak-probe' ||
      !/^[a-f0-9]{64}$/.test(backend.logConfigurationSha256 || '') || backend.probeRequestCount !== 1 ||
      (previousBackendConfigurationSha &&
       backend.logConfigurationSha256 !== previousBackendConfigurationSha) ||
      !/^[a-f0-9]{64}$/.test(backend.logSetSha256 || '') || backend.apiV1FilesRequestCount !== 0 ||
      !Number.isSafeInteger(backend.uploadsGetHeadRequestCount) || backend.uploadsGetHeadRequestCount < 0 ||
      backend.uploadsSuccessfulGetHeadCount !== 0 || backend.rotationContinuityPassed !== true ||
      backend.futureSkewPassed !== true || backend.windowStartedAt !== new Date(previousAt).toISOString()) fail();
  let previousPath = '';
  for (const file of backend.logFiles) {
    if (!exactKeys(file, backendLogFileKeys) || !/^[a-f0-9]{64}$/.test(file.pathSha256 || '') ||
        file.pathSha256 <= previousPath || !decimal(file.device) || !decimal(file.inode) ||
        !decimal(file.generation) || !decimal(file.firstByteOffset) || !decimal(file.lastByteOffset) ||
        !decimal(file.bytes) || BigInt(file.lastByteOffset) < BigInt(file.firstByteOffset) ||
        BigInt(file.bytes) !== BigInt(file.lastByteOffset) - BigInt(file.firstByteOffset) ||
        !/^[a-f0-9]{64}$/.test(file.sha256 || '') || !Number.isFinite(Date.parse(file.mtime))) fail();
    previousPath = file.pathSha256;
  }
  if (createHash('sha256').update(JSON.stringify(backend.logFiles)).digest('hex') !== backend.logSetSha256) fail();
  const observedAt = Date.parse(value.observedAt);
  const gapSeconds = Math.floor((observedAt - previousAt) / 1000);
  if (!Number.isFinite(observedAt) || observedAt < previousAt || gapSeconds > 93600 ||
      observedAt > Date.now() + 120000 || Date.parse(frontend.windowEndedAt) > observedAt + 120000 ||
      observedAt - Date.parse(frontend.windowEndedAt) > 93600000 ||
      Date.parse(backend.windowEndedAt) > observedAt + 120000 ||
      observedAt - Date.parse(backend.windowEndedAt) > 300000) fail();
  maxGapSeconds = Math.max(maxGapSeconds, gapSeconds);
  const sha = createHash('sha256').update(bytes).digest('hex');
  if (!firstSha) { firstSha = sha; firstAt = value.observedAt; }
  lastSha = sha;
  previousSha = sha;
  previousAt = observedAt;
  previousFrontendSequence = frontend.sequence;
  previousFrontendSha = frontend.evidenceSha256;
  previousFrontendSignatureSha = frontend.evidenceSignatureSha256;
  previousFrontendEnded = Date.parse(frontend.windowEndedAt);
  if (firstFrontendStarted === null) firstFrontendStarted = frontend.chainStartedAt;
  previousBackendFiles = backend.logFiles;
  previousBackendConfigurationSha = backend.logConfigurationSha256;
  lastBackendLogSetSha = backend.logSetSha256;
  lastBackendEnded = backend.windowEndedAt;
}
process.stdout.write(JSON.stringify({ heartbeatCount: names.length, firstHeartbeatSha256: firstSha,
  lastHeartbeatSha256: lastSha, firstObservedAt: firstAt,
  lastObservedAt: new Date(previousAt).toISOString(), maximumGapSeconds: maxGapSeconds,
  lastFrontendSequence: previousFrontendSequence, lastFrontendEvidenceSha256: previousFrontendSha,
  lastFrontendEvidenceSignatureSha256: previousFrontendSignatureSha,
  firstFrontendWindowStartedAt: firstFrontendStarted,
  lastFrontendWindowEndedAt: new Date(previousFrontendEnded).toISOString(),
  lastBackendLogSetSha256: lastBackendLogSetSha, lastBackendWindowEndedAt: lastBackendEnded,
  lastBackendLogFiles: previousBackendFiles }));
NODE
}

identity_avatar_run_soak_heartbeat_locked() (
	identity_avatar_validate_marker
	identity_avatar_runtime_stability_verify_or_adopt || return 1
	identity_avatar_validate_marker
	[[ "$(identity_avatar_marker_value phase)" == 'client-switched' ]] ||
		identity_avatar_fail 'soak heartbeat requires phase=client-switched' || return 1
	identity_avatar_validate_soak_timer_installation ||
		identity_avatar_fail 'bound daily backend avatar soak timer is not active' || return 1
	local owner_revision runtime_revision initial_client_revision client_revision client_sha client_retarget_sha
	local runtime_retarget_sha reset_anchor_sha
	local client_release_sha client_release_signature_sha writer_sha policy_sha inventory_sha status_sha revocation_sha smoke_sha
	local client_writer_sha client_policy_sha client_smoke_sha client_record client_verified_at runtime_verified_at
	local reference_sha client_switch_reference_sha client_ready_sha client_ready_signature_sha identity_database_id
	local boundary probe chain sequence previous file data client_probe frontend_soak backend_log
	local backend_window_started previous_backend_files client_process_started_at
	local stability_chain stability_terminal stability_generation stability_sha stability_runtimes stability_frontend
	owner_revision="$(identity_avatar_marker_value server_revision)" || return 1
	runtime_revision="$(identity_avatar_marker_value runtime_revision)" || return 1
	initial_client_revision="$(identity_avatar_marker_value client_revision)" || return 1
	client_revision="$(identity_avatar_marker_value current_client_revision)" || return 1
	client_sha="$(identity_avatar_marker_value client_evidence_sha256)" || return 1
	client_retarget_sha="$(identity_avatar_marker_value client_retarget_evidence_sha256)" || return 1
	runtime_retarget_sha="$(identity_avatar_marker_value runtime_retarget_evidence_sha256)" || return 1
	writer_sha="$(identity_avatar_marker_value writer_fence_evidence_sha256)" || return 1
	policy_sha="$(identity_avatar_marker_value storage_policy_evidence_sha256)" || return 1
	inventory_sha="$(identity_avatar_marker_value inventory_manifest_sha256)" || return 1
	status_sha="$(identity_avatar_marker_value status_manifest_sha256)" || return 1
	revocation_sha="$(identity_avatar_marker_value revocation_evidence_sha256)" || return 1
	smoke_sha="$(identity_avatar_marker_value authenticated_smoke_evidence_sha256)" || return 1
	stability_chain="$(identity_avatar_validate_runtime_stability_chain terminal-live)" || return 1
	stability_terminal="$(IDENTITY_AVATAR_CHAIN="$stability_chain" node -e 'process.stdout.write(JSON.stringify(JSON.parse(process.env.IDENTITY_AVATAR_CHAIN).terminal))')" || return 1
	stability_generation="$(IDENTITY_AVATAR_TERMINAL="$stability_terminal" node -e 'process.stdout.write(String(JSON.parse(process.env.IDENTITY_AVATAR_TERMINAL).generation))')" || return 1
	stability_sha="$(IDENTITY_AVATAR_CHAIN="$stability_chain" node -e 'process.stdout.write(JSON.parse(process.env.IDENTITY_AVATAR_CHAIN).terminalSha256)')" || return 1
	stability_runtimes="$(IDENTITY_AVATAR_TERMINAL="$stability_terminal" node -e 'process.stdout.write(JSON.stringify(JSON.parse(process.env.IDENTITY_AVATAR_TERMINAL).currentRuntimes))')" || return 1
	stability_frontend="$(IDENTITY_AVATAR_TERMINAL="$stability_terminal" node -e 'process.stdout.write(JSON.stringify(JSON.parse(process.env.IDENTITY_AVATAR_TERMINAL).frontendBinding))')" || return 1
	boundary="$(IDENTITY_AVATAR_TERMINAL="$stability_terminal" node -e 'process.stdout.write(JSON.parse(process.env.IDENTITY_AVATAR_TERMINAL).runtimeStableSince)')" || return 1
	reset_anchor_sha="$stability_sha"
	client_writer_sha="$(identity_avatar_json_string_field "$identity_avatar_client_evidence" writerFenceEvidenceSha256)" || return 1
	client_policy_sha="$(identity_avatar_json_string_field "$identity_avatar_client_evidence" storagePolicyEvidenceSha256)" || return 1
	client_smoke_sha="$(identity_avatar_json_string_field "$identity_avatar_client_evidence" authenticatedSmokeEvidenceSha256)" || return 1
	reference_sha="$(identity_avatar_json_string_field "$identity_avatar_client_evidence" \
		preClientReferenceZeroEvidenceSha256)" || return 1
	client_switch_reference_sha="$(identity_avatar_json_string_field "$identity_avatar_client_evidence" \
		clientSwitchReferenceZeroEvidenceSha256)" || return 1
	client_ready_sha="$(identity_avatar_json_string_field "$identity_avatar_client_evidence" \
		clientReadyEvidenceSha256)" || return 1
	client_ready_signature_sha="$(identity_avatar_json_string_field "$identity_avatar_client_evidence" \
		clientReadyEvidenceSignatureSha256)" || return 1
	identity_database_id="$(identity_avatar_json_string_field "$identity_avatar_client_evidence" \
		identityDatabaseId)" || return 1
	[[ "$runtime_revision" == "$EXPECTED_REVISION" &&
		"$(identity_avatar_sha256 "$identity_avatar_client_evidence")" == "$client_sha" &&
		"$(identity_avatar_sha256 "$identity_avatar_reference_zero_evidence")" == "$reference_sha" &&
		"$(identity_avatar_sha256 "$identity_avatar_client_switch_reference_zero_evidence")" == \
			"$client_switch_reference_sha" &&
		"$(identity_avatar_sha256 "$identity_avatar_client_ready_body")" == "$client_ready_sha" &&
		"$(identity_avatar_sha256 "$identity_avatar_client_ready_signature")" == \
			"$client_ready_signature_sha" ]] || return 1
	identity_avatar_validate_reference_zero_evidence "$identity_avatar_reference_zero_evidence" \
		identity-avatar-legacy-reference-zero historical "$client_writer_sha" "$client_policy_sha" || return 1
	identity_avatar_validate_reference_zero_evidence "$identity_avatar_client_switch_reference_zero_evidence" \
		identity-avatar-client-switch-reference-zero historical "$client_writer_sha" "$client_policy_sha" || return 1
	identity_avatar_verify_detached_lifecycle_evidence "$identity_avatar_client_evidence" \
		identity-avatar-client-switch || return 1
	if [[ "$client_revision" == "$initial_client_revision" ]]; then
		[[ "$client_retarget_sha" == 'pending' ]] || return 1
		client_release_sha="$(identity_avatar_json_string_field "$identity_avatar_client_evidence" releaseEvidenceSha256)" || return 1
		client_probe="$(identity_avatar_verify_live_client_switch "$client_revision" "$client_release_sha")" || return 1
		identity_avatar_validate_client_evidence "$client_revision" "$client_writer_sha" "$client_policy_sha" \
			"$client_smoke_sha" "$reference_sha" "$client_switch_reference_sha" \
			"$client_ready_sha" "$client_ready_signature_sha" "$identity_database_id" \
			"$client_release_sha" "$client_probe" || return 1
		client_release_signature_sha="$(IDENTITY_AVATAR_CLIENT_PROBE="$client_probe" node -e '
const value=JSON.parse(process.env.IDENTITY_AVATAR_CLIENT_PROBE);process.stdout.write(value.releaseEvidenceSignatureSha256);')" || return 1
		client_verified_at="$(identity_avatar_json_string_field "$identity_avatar_client_evidence" verifiedAt)" || return 1
	else
		[[ "$client_retarget_sha" =~ ^[0-9a-f]{64}$ ]] || return 1
		client_record="$(identity_avatar_validate_client_retarget_chain)" || return 1
		client_release_sha="$(IDENTITY_AVATAR_CLIENT_RECORD="$client_record" node -e '
const value=JSON.parse(process.env.IDENTITY_AVATAR_CLIENT_RECORD);process.stdout.write(value.releaseEvidenceSha256);')" || return 1
		client_release_signature_sha="$(IDENTITY_AVATAR_CLIENT_RECORD="$client_record" node -e '
const value=JSON.parse(process.env.IDENTITY_AVATAR_CLIENT_RECORD);process.stdout.write(value.releaseEvidenceSignatureSha256);')" || return 1
		client_verified_at="$(IDENTITY_AVATAR_CLIENT_RECORD="$client_record" node -e '
const value=JSON.parse(process.env.IDENTITY_AVATAR_CLIENT_RECORD);process.stdout.write(value.verifiedAt);')" || return 1
		client_probe="$(identity_avatar_verify_live_client_switch "$client_revision" "$client_release_sha")" || return 1
		IDENTITY_AVATAR_CLIENT_RECORD="$client_record" IDENTITY_AVATAR_CLIENT_PROBE="$client_probe" node -e '
const record=JSON.parse(process.env.IDENTITY_AVATAR_CLIENT_RECORD),probe=JSON.parse(process.env.IDENTITY_AVATAR_CLIENT_PROBE);
for(const [a,b] of [[record.currentClientRevision,probe.deployedRevision],[record.releaseEvidenceSha256,probe.releaseEvidenceSha256],
	[record.releaseEvidenceSignatureSha256,probe.releaseEvidenceSignatureSha256],[record.releaseTreeSha256,probe.releaseTreeSha256],
	[record.releaseFullManifestSha256,probe.releaseFullManifestSha256]])if(a!==b)process.exit(1);' || return 1
	fi
	client_process_started_at="$(IDENTITY_AVATAR_FRONTEND="$stability_frontend" node -e 'process.stdout.write(JSON.parse(process.env.IDENTITY_AVATAR_FRONTEND).processStartedAt)')" || return 1
	IDENTITY_AVATAR_FRONTEND="$stability_frontend" IDENTITY_AVATAR_PROBE="$client_probe" \
	IDENTITY_AVATAR_RELEASE_SHA="$client_release_sha" IDENTITY_AVATAR_RELEASE_SIGNATURE_SHA="$client_release_signature_sha" node -e '
const binding=JSON.parse(process.env.IDENTITY_AVATAR_FRONTEND),probe=JSON.parse(process.env.IDENTITY_AVATAR_PROBE);
if(binding.clientRevision!==probe.deployedRevision||binding.releaseEvidenceSha256!==process.env.IDENTITY_AVATAR_RELEASE_SHA||
  binding.releaseEvidenceSignatureSha256!==process.env.IDENTITY_AVATAR_RELEASE_SIGNATURE_SHA||
  binding.processStartedAt!==probe.processStartedAt)process.exit(1);' || return 1
	if [[ ! -e "$identity_avatar_soak_heartbeat_root" && ! -L "$identity_avatar_soak_heartbeat_root" ]]; then
		mkdir -m 700 "$identity_avatar_soak_heartbeat_root"
		chown 0:0 "$identity_avatar_soak_heartbeat_root"
	fi
	[[ -d "$identity_avatar_soak_heartbeat_root" && ! -L "$identity_avatar_soak_heartbeat_root" &&
		"$(stat -c '%u:%g:%a' "$identity_avatar_soak_heartbeat_root")" == '0:0:700' ]] || return 1
	sequence="$(find "$identity_avatar_soak_heartbeat_root" -mindepth 1 -maxdepth 1 -type f \
		-name 'heartbeat-*.json' | wc -l | tr -d ' ')" || return 1
	[[ "$sequence" =~ ^[0-9]+$ ]] || return 1
	if ((sequence == 0)); then
		previous="$reset_anchor_sha"
		backend_window_started="$boundary"
		previous_backend_files='[]'
	else
		chain="$(identity_avatar_validate_soak_heartbeat_chain "$client_revision" "$client_sha" \
			"$client_retarget_sha" "$runtime_retarget_sha" "$client_release_sha" "$client_release_signature_sha" \
			"$client_process_started_at" "$writer_sha" "$policy_sha" "$inventory_sha" "$status_sha" \
			"$revocation_sha" "$smoke_sha" "$boundary" "$reset_anchor_sha" \
			"$stability_generation" "$stability_sha")" || return 1
		previous="$(IDENTITY_AVATAR_CHAIN="$chain" node -e '
const value = JSON.parse(process.env.IDENTITY_AVATAR_CHAIN);
process.stdout.write(value.lastHeartbeatSha256);
')" || return 1
		backend_window_started="$(IDENTITY_AVATAR_CHAIN="$chain" node -e '
const value=JSON.parse(process.env.IDENTITY_AVATAR_CHAIN);process.stdout.write(value.lastObservedAt);')" || return 1
		previous_backend_files="$(IDENTITY_AVATAR_CHAIN="$chain" node -e '
const value=JSON.parse(process.env.IDENTITY_AVATAR_CHAIN);process.stdout.write(JSON.stringify(value.lastBackendLogFiles));')" || return 1
	fi
	frontend_soak="$(identity_avatar_verify_frontend_soak_chain "$client_revision" \
		"$client_release_sha" "$client_process_started_at")" ||
		identity_avatar_fail 'signed frontend access-log soak evidence is invalid or unavailable' || return 1
	backend_log="$(identity_avatar_backend_access_log_probe "$backend_window_started" \
		"$previous_backend_files")" ||
		identity_avatar_fail 'backend access-log continuity or legacy-request gate failed' || return 1
	probe="$(IDENTITY_AVATAR_SOAK_STABILITY_RUNTIMES="$stability_runtimes" \
		identity_avatar_soak_runtime_probe "$client_revision" "$client_probe" \
		"$frontend_soak" "$backend_log")" ||
		identity_avatar_fail 'soak runtime probe failed' || return 1
	sequence=$((sequence + 1))
	printf -v file '%s/heartbeat-%06d.json' "$identity_avatar_soak_heartbeat_root" "$sequence"
	data="$(IDENTITY_AVATAR_SOAK_PROBE="$probe" EXPECTED_REVISION="$EXPECTED_REVISION" \
		IDENTITY_AVATAR_OWNERSHIP_REVISION="$(identity_avatar_marker_value server_revision)" \
		IDENTITY_AVATAR_CLIENT_REVISION="$client_revision" IDENTITY_AVATAR_SEQUENCE="$sequence" \
		IDENTITY_AVATAR_STABILITY_GENERATION="$stability_generation" \
		IDENTITY_AVATAR_STABILITY_SHA="$stability_sha" \
		IDENTITY_AVATAR_PREVIOUS_SHA="$previous" IDENTITY_AVATAR_CLIENT_SHA="$client_sha" \
		IDENTITY_AVATAR_CLIENT_RETARGET_SHA="$client_retarget_sha" \
		IDENTITY_AVATAR_RUNTIME_RETARGET_SHA="$runtime_retarget_sha" \
		IDENTITY_AVATAR_WRITER_SHA="$writer_sha" IDENTITY_AVATAR_POLICY_SHA="$policy_sha" \
		IDENTITY_AVATAR_INVENTORY_SHA="$inventory_sha" IDENTITY_AVATAR_STATUS_SHA="$status_sha" \
		IDENTITY_AVATAR_REVOCATION_SHA="$revocation_sha" IDENTITY_AVATAR_SMOKE_SHA="$smoke_sha" \
		IDENTITY_AVATAR_OBSERVED_AT="$(date -u +%Y-%m-%dT%H:%M:%SZ)" node <<'NODE'
const probe = JSON.parse(process.env.IDENTITY_AVATAR_SOAK_PROBE);
process.stdout.write(JSON.stringify({
  serverRevision: process.env.IDENTITY_AVATAR_OWNERSHIP_REVISION,
  currentRuntimeRevision: process.env.EXPECTED_REVISION,
  clientRevision: process.env.IDENTITY_AVATAR_CLIENT_REVISION,
  runtimeStabilityGeneration: Number(process.env.IDENTITY_AVATAR_STABILITY_GENERATION),
  runtimeStabilityEvidenceSha256: process.env.IDENTITY_AVATAR_STABILITY_SHA,
  sequence: Number(process.env.IDENTITY_AVATAR_SEQUENCE),
  previousEvidenceSha256: process.env.IDENTITY_AVATAR_PREVIOUS_SHA,
	  clientEvidenceSha256: process.env.IDENTITY_AVATAR_CLIENT_SHA,
	  clientRetargetEvidenceSha256: process.env.IDENTITY_AVATAR_CLIENT_RETARGET_SHA,
	  runtimeRetargetEvidenceSha256: process.env.IDENTITY_AVATAR_RUNTIME_RETARGET_SHA,
  writerFenceEvidenceSha256: process.env.IDENTITY_AVATAR_WRITER_SHA,
  storagePolicyEvidenceSha256: process.env.IDENTITY_AVATAR_POLICY_SHA,
  inventoryManifestSha256: process.env.IDENTITY_AVATAR_INVENTORY_SHA,
  statusManifestSha256: process.env.IDENTITY_AVATAR_STATUS_SHA,
  revocationEvidenceSha256: process.env.IDENTITY_AVATAR_REVOCATION_SHA,
  authenticatedSmokeEvidenceSha256: process.env.IDENTITY_AVATAR_SMOKE_SHA,
  ...probe,
  observedAt: process.env.IDENTITY_AVATAR_OBSERVED_AT,
}));
NODE
)" || return 1
	identity_avatar_write_signed_json_evidence "$file" identity-avatar-soak-heartbeat "$data"
	identity_avatar_validate_soak_heartbeat_chain "$client_revision" "$client_sha" "$client_retarget_sha" \
		"$runtime_retarget_sha" "$client_release_sha" "$client_release_signature_sha" "$client_process_started_at" \
		"$writer_sha" "$policy_sha" "$inventory_sha" "$status_sha" "$revocation_sha" \
		"$smoke_sha" "$boundary" "$reset_anchor_sha" "$stability_generation" "$stability_sha" >/dev/null
	printf 'identity_avatar_soak_heartbeat=passed\n'
	printf 'identity_avatar_soak_heartbeat_sequence=%s\n' "$sequence"
)

identity_avatar_run_soak_heartbeat() (
	identity_avatar_require_production_inputs
	acquire_production_deploy_lock 'Identity avatar soak heartbeat'
	identity_avatar_run_soak_heartbeat_locked
)

identity_avatar_validate_soak_evidence() {
	[[ $# -eq 13 && "$1" =~ ^[0-9a-f]{40}$ && "$2" =~ ^[0-9a-f]{64}$ &&
		"$3" =~ ^(pending|[0-9a-f]{64})$ && "$4" =~ ^(pending|[0-9a-f]{64})$ &&
		"${12}" =~ ^(0|[1-9]|[1-5][0-9]|6[0-4])$ && "${13}" =~ ^[0-9a-f]{64}$ ]] || return 1
	identity_avatar_validate_private_file "$identity_avatar_soak_evidence" || return 1
	identity_avatar_validate_private_file "$identity_avatar_signing_public_key" || return 1
	local ownership_revision
	ownership_revision="$(identity_avatar_marker_value server_revision)" || return 1
	IDENTITY_AVATAR_SOAK_FILE="$identity_avatar_soak_evidence" \
	IDENTITY_AVATAR_SOAK_PUBLIC_KEY="$identity_avatar_signing_public_key" \
	EXPECTED_REVISION="$EXPECTED_REVISION" IDENTITY_AVATAR_OWNERSHIP_REVISION="$ownership_revision" \
	IDENTITY_AVATAR_CLIENT_REVISION="$1" \
	IDENTITY_AVATAR_CLIENT_SHA="$2" IDENTITY_AVATAR_CLIENT_RETARGET_SHA="$3" \
	IDENTITY_AVATAR_RUNTIME_RETARGET_SHA="$4" \
	IDENTITY_AVATAR_WRITER_SHA="$5" IDENTITY_AVATAR_POLICY_SHA="$6" \
	IDENTITY_AVATAR_INVENTORY_SHA="$7" IDENTITY_AVATAR_STATUS_SHA="$8" \
	IDENTITY_AVATAR_REVOCATION_SHA="$9" IDENTITY_AVATAR_SMOKE_SHA="${10}" \
	IDENTITY_AVATAR_CHAIN="${11}" IDENTITY_AVATAR_STABILITY_GENERATION="${12}" \
	IDENTITY_AVATAR_STABILITY_SHA="${13}" node <<'NODE'
const { verify } = require('node:crypto');
const { readFileSync } = require('node:fs');
let value;
let chain;
try {
  value = JSON.parse(readFileSync(process.env.IDENTITY_AVATAR_SOAK_FILE, 'utf8'));
  chain = JSON.parse(process.env.IDENTITY_AVATAR_CHAIN);
} catch { process.exit(1); }
const keys = ['version', 'kind', 'serverRevision', 'currentRuntimeRevision', 'clientRevision',
  'runtimeStabilityGeneration', 'runtimeStabilityEvidenceSha256', 'clientEvidenceSha256',
	  'clientRetargetEvidenceSha256', 'runtimeRetargetEvidenceSha256',
  'writerFenceEvidenceSha256', 'storagePolicyEvidenceSha256', 'inventoryManifestSha256',
  'statusManifestSha256', 'revocationEvidenceSha256', 'authenticatedSmokeEvidenceSha256',
  'firstHeartbeatSha256', 'lastHeartbeatSha256', 'heartbeatCount', 'observationStartedAt',
  'observationEndedAt', 'lastFrontendLogEvidenceSha256',
  'lastFrontendLogEvidenceSignatureSha256', 'lastFrontendLogSequence',
  'frontendObservationStartedAt', 'frontendObservationEndedAt', 'lastBackendLogSetSha256',
  'backendObservationEndedAt', 'requiredSeconds', 'maximumGapSeconds', 'continuityPassed',
  'frontendLogContinuityPassed', 'backendLogContinuityPassed', 'legacyTrafficZeroPassed',
  'bucketVersioningStablePassed',
  'ownershipActivePassed', 'legacyRoutesFencedPassed', 'clientRevisionStablePassed',
  'runtimeContainersStablePassed', 'verifiedAt', 'signature'];
if (JSON.stringify(Object.keys(value)) !== JSON.stringify(keys)) process.exit(1);
const { signature, ...payload } = value;
const exact = [
  ['serverRevision', process.env.IDENTITY_AVATAR_OWNERSHIP_REVISION],
  ['currentRuntimeRevision', process.env.EXPECTED_REVISION],
	  ['clientRevision', process.env.IDENTITY_AVATAR_CLIENT_REVISION],
	  ['runtimeStabilityGeneration', Number(process.env.IDENTITY_AVATAR_STABILITY_GENERATION)],
	  ['runtimeStabilityEvidenceSha256', process.env.IDENTITY_AVATAR_STABILITY_SHA],
	  ['clientEvidenceSha256', process.env.IDENTITY_AVATAR_CLIENT_SHA],
	  ['clientRetargetEvidenceSha256', process.env.IDENTITY_AVATAR_CLIENT_RETARGET_SHA],
	  ['runtimeRetargetEvidenceSha256', process.env.IDENTITY_AVATAR_RUNTIME_RETARGET_SHA],
  ['writerFenceEvidenceSha256', process.env.IDENTITY_AVATAR_WRITER_SHA],
  ['storagePolicyEvidenceSha256', process.env.IDENTITY_AVATAR_POLICY_SHA],
  ['inventoryManifestSha256', process.env.IDENTITY_AVATAR_INVENTORY_SHA],
  ['statusManifestSha256', process.env.IDENTITY_AVATAR_STATUS_SHA],
  ['revocationEvidenceSha256', process.env.IDENTITY_AVATAR_REVOCATION_SHA],
  ['authenticatedSmokeEvidenceSha256', process.env.IDENTITY_AVATAR_SMOKE_SHA],
  ['firstHeartbeatSha256', chain.firstHeartbeatSha256],
  ['lastHeartbeatSha256', chain.lastHeartbeatSha256],
  ['heartbeatCount', chain.heartbeatCount],
  ['observationEndedAt', chain.lastObservedAt],
  ['lastFrontendLogEvidenceSha256', chain.lastFrontendEvidenceSha256],
  ['lastFrontendLogEvidenceSignatureSha256', chain.lastFrontendEvidenceSignatureSha256],
  ['lastFrontendLogSequence', chain.lastFrontendSequence],
  ['frontendObservationStartedAt', chain.firstFrontendWindowStartedAt],
  ['frontendObservationEndedAt', chain.lastFrontendWindowEndedAt],
  ['lastBackendLogSetSha256', chain.lastBackendLogSetSha256],
  ['backendObservationEndedAt', chain.lastBackendWindowEndedAt],
  ['maximumGapSeconds', chain.maximumGapSeconds],
];
if (value.version !== 1 || value.kind !== 'identity-avatar-soak-complete' ||
    exact.some(([key, expected]) => value[key] !== expected) ||
    value.requiredSeconds !== 604800 || value.continuityPassed !== true ||
    value.frontendLogContinuityPassed !== true || value.backendLogContinuityPassed !== true ||
    value.legacyTrafficZeroPassed !== true || value.bucketVersioningStablePassed !== true ||
    value.ownershipActivePassed !== true || value.legacyRoutesFencedPassed !== true ||
    value.clientRevisionStablePassed !== true || value.runtimeContainersStablePassed !== true ||
    !/^[0-9TZ:.-]+$/.test(value.observationStartedAt || '') ||
    value.verifiedAt !== value.observationEndedAt || typeof signature !== 'string' ||
    Date.parse(value.observationEndedAt) - Date.parse(value.observationStartedAt) < 604800000 ||
    !verify(null, Buffer.from(JSON.stringify(payload)),
      readFileSync(process.env.IDENTITY_AVATAR_SOAK_PUBLIC_KEY),
      Buffer.from(signature, 'base64'))) process.exit(1);
NODE
}

identity_avatar_validate_soak_completion_window() {
	[[ $# -eq 2 && "$2" =~ ^[0-9TZ:.-]+$ &&
		("${IDENTITY_AVATAR_TEST_NOW_MS:-}" == '' ||
			("${CI:-}" == 'true' && "$IDENTITY_AVATAR_TEST_NOW_MS" =~ ^[0-9]+$)) ]] || return 1
	IDENTITY_AVATAR_CHAIN="$1" IDENTITY_AVATAR_BOUNDARY="$2" \
	IDENTITY_AVATAR_NOW_MS="${IDENTITY_AVATAR_TEST_NOW_MS:-}" node <<'NODE'
const value = JSON.parse(process.env.IDENTITY_AVATAR_CHAIN);
const boundary = Date.parse(process.env.IDENTITY_AVATAR_BOUNDARY);
const ended = Date.parse(value.lastObservedAt);
const frontendStarted = Date.parse(value.firstFrontendWindowStartedAt);
const frontendEnded = Date.parse(value.lastFrontendWindowEndedAt);
const backendEnded = Date.parse(value.lastBackendWindowEndedAt);
const now = process.env.IDENTITY_AVATAR_NOW_MS ? Number(process.env.IDENTITY_AVATAR_NOW_MS) : Date.now();
if (!Number.isSafeInteger(now) || !Number.isSafeInteger(value.heartbeatCount) || value.heartbeatCount < 8 ||
    !Number.isFinite(boundary) || !Number.isFinite(ended) || !Number.isFinite(frontendStarted) ||
    !Number.isFinite(frontendEnded) || !Number.isFinite(backendEnded) ||
    ended - boundary < 604800000 || frontendStarted > boundary ||
    frontendEnded - boundary < 604800000 || backendEnded - boundary < 604800000 ||
    now - ended > 93600000 || value.maximumGapSeconds > 93600 ||
    !Number.isSafeInteger(value.lastFrontendSequence) || value.lastFrontendSequence < 8 ||
    now - Date.parse(value.lastFrontendWindowEndedAt) > 93600000 ||
    now - Date.parse(value.lastBackendWindowEndedAt) > 93600000) process.exit(1);
NODE
}

identity_avatar_run_verify_soak() (
	[[ "$IDENTITY_AVATAR_SOAK_SECONDS" == '604800' ]] ||
		identity_avatar_fail 'Identity avatar production soak is exactly seven days' || return 1
	identity_avatar_require_production_inputs
	acquire_production_deploy_lock 'Identity avatar seven-day soak completion'
	identity_avatar_validate_marker
	identity_avatar_runtime_stability_verify_or_adopt || return 1
	identity_avatar_validate_marker
	local phase
	phase="$(identity_avatar_marker_value phase)" || return 1
	[[ "$phase" =~ ^(client-switched|soak-complete)$ ]] ||
		identity_avatar_fail 'soak completion requires phase=client-switched' || return 1
	if [[ "$phase" == 'client-switched' ]]; then
		identity_avatar_run_soak_heartbeat_locked
		identity_avatar_validate_marker
	fi
	local initial_client_revision client_revision client_sha client_retarget_sha runtime_retarget_sha client_record
	local client_release_sha client_release_signature_sha client_process_started_at client_verified_at runtime_verified_at
	local writer_sha policy_sha inventory_sha status_sha revocation_sha smoke_sha
	local snapshot_sha migration_sha migration_ready_at migrated_at client_switched_at boundary reset_anchor_sha chain data
	local soak_sha soak_verified_at
	local stability_chain stability_terminal stability_generation stability_sha stability_frontend
	initial_client_revision="$(identity_avatar_marker_value client_revision)" || return 1
	client_revision="$(identity_avatar_marker_value current_client_revision)" || return 1
	client_sha="$(identity_avatar_marker_value client_evidence_sha256)" || return 1
	client_retarget_sha="$(identity_avatar_marker_value client_retarget_evidence_sha256)" || return 1
	runtime_retarget_sha="$(identity_avatar_marker_value runtime_retarget_evidence_sha256)" || return 1
	writer_sha="$(identity_avatar_marker_value writer_fence_evidence_sha256)" || return 1
	policy_sha="$(identity_avatar_marker_value storage_policy_evidence_sha256)" || return 1
	snapshot_sha="$(identity_avatar_marker_value uploads_snapshot_evidence_sha256)" || return 1
	inventory_sha="$(identity_avatar_marker_value inventory_manifest_sha256)" || return 1
	migration_sha="$(identity_avatar_marker_value migration_manifest_sha256)" || return 1
	status_sha="$(identity_avatar_marker_value status_manifest_sha256)" || return 1
	revocation_sha="$(identity_avatar_marker_value revocation_evidence_sha256)" || return 1
	smoke_sha="$(identity_avatar_marker_value authenticated_smoke_evidence_sha256)" || return 1
	migration_ready_at="$(identity_avatar_marker_value migration_ready_at)" || return 1
	migrated_at="$(identity_avatar_marker_value migrated_at)" || return 1
	client_switched_at="$(identity_avatar_marker_value client_switched_at)" || return 1
	stability_chain="$(identity_avatar_validate_runtime_stability_chain terminal-live)" || return 1
	stability_terminal="$(IDENTITY_AVATAR_CHAIN="$stability_chain" node -e 'process.stdout.write(JSON.stringify(JSON.parse(process.env.IDENTITY_AVATAR_CHAIN).terminal))')" || return 1
	stability_generation="$(IDENTITY_AVATAR_TERMINAL="$stability_terminal" node -e 'process.stdout.write(String(JSON.parse(process.env.IDENTITY_AVATAR_TERMINAL).generation))')" || return 1
	stability_sha="$(IDENTITY_AVATAR_CHAIN="$stability_chain" node -e 'process.stdout.write(JSON.parse(process.env.IDENTITY_AVATAR_CHAIN).terminalSha256)')" || return 1
	stability_frontend="$(IDENTITY_AVATAR_TERMINAL="$stability_terminal" node -e 'process.stdout.write(JSON.stringify(JSON.parse(process.env.IDENTITY_AVATAR_TERMINAL).frontendBinding))')" || return 1
	boundary="$(IDENTITY_AVATAR_TERMINAL="$stability_terminal" node -e 'process.stdout.write(JSON.parse(process.env.IDENTITY_AVATAR_TERMINAL).runtimeStableSince)')" || return 1
	reset_anchor_sha="$stability_sha"
	if [[ "$client_revision" == "$initial_client_revision" ]]; then
		[[ "$client_retarget_sha" == 'pending' ]] || return 1
		client_release_sha="$(identity_avatar_json_string_field "$identity_avatar_client_evidence" releaseEvidenceSha256)" || return 1
		client_release_signature_sha="$(identity_avatar_json_string_field "$identity_avatar_client_evidence" releaseEvidenceSignatureSha256)" || return 1
		client_verified_at="$(identity_avatar_json_string_field "$identity_avatar_client_evidence" verifiedAt)" || return 1
	else
		client_record="$(identity_avatar_validate_client_retarget_chain)" || return 1
		client_release_sha="$(IDENTITY_AVATAR_CLIENT_RECORD="$client_record" node -e 'process.stdout.write(JSON.parse(process.env.IDENTITY_AVATAR_CLIENT_RECORD).releaseEvidenceSha256)')" || return 1
		client_release_signature_sha="$(IDENTITY_AVATAR_CLIENT_RECORD="$client_record" node -e 'process.stdout.write(JSON.parse(process.env.IDENTITY_AVATAR_CLIENT_RECORD).releaseEvidenceSignatureSha256)')" || return 1
		client_verified_at="$(IDENTITY_AVATAR_CLIENT_RECORD="$client_record" node -e 'process.stdout.write(JSON.parse(process.env.IDENTITY_AVATAR_CLIENT_RECORD).verifiedAt)')" || return 1
	fi
	client_process_started_at="$(IDENTITY_AVATAR_FRONTEND="$stability_frontend" node -e 'process.stdout.write(JSON.parse(process.env.IDENTITY_AVATAR_FRONTEND).processStartedAt)')" || return 1
	IDENTITY_AVATAR_FRONTEND="$stability_frontend" IDENTITY_AVATAR_CLIENT_REVISION="$client_revision" \
	IDENTITY_AVATAR_RELEASE_SHA="$client_release_sha" IDENTITY_AVATAR_RELEASE_SIGNATURE_SHA="$client_release_signature_sha" node -e '
const binding=JSON.parse(process.env.IDENTITY_AVATAR_FRONTEND);
if(binding.clientRevision!==process.env.IDENTITY_AVATAR_CLIENT_REVISION||
  binding.releaseEvidenceSha256!==process.env.IDENTITY_AVATAR_RELEASE_SHA||
  binding.releaseEvidenceSignatureSha256!==process.env.IDENTITY_AVATAR_RELEASE_SIGNATURE_SHA)process.exit(1);' || return 1
	chain="$(identity_avatar_validate_soak_heartbeat_chain "$client_revision" "$client_sha" \
		"$client_retarget_sha" "$runtime_retarget_sha" "$client_release_sha" "$client_release_signature_sha" \
		"$client_process_started_at" "$writer_sha" "$policy_sha" "$inventory_sha" "$status_sha" \
		"$revocation_sha" "$smoke_sha" "$boundary" "$reset_anchor_sha" \
		"$stability_generation" "$stability_sha")" || return 1
	identity_avatar_validate_soak_completion_window "$chain" "$boundary" || return 1
	if [[ "$phase" == 'soak-complete' ]]; then
		soak_sha="$(identity_avatar_marker_value soak_evidence_sha256)" || return 1
		[[ "$(identity_avatar_sha256 "$identity_avatar_soak_evidence")" == "$soak_sha" ]] || return 1
		identity_avatar_validate_soak_evidence "$client_revision" "$client_sha" "$client_retarget_sha" \
			"$runtime_retarget_sha" \
			"$writer_sha" "$policy_sha" "$inventory_sha" "$status_sha" "$revocation_sha" "$smoke_sha" "$chain" \
			"$stability_generation" "$stability_sha"
		identity_avatar_validate_soak_timer_installation || return 1
		printf 'identity_avatar_soak=validated\n'
		printf 'identity_avatar_phase=soak-complete\n'
		return 0
	fi
	if [[ ! -e "$identity_avatar_soak_evidence" && ! -L "$identity_avatar_soak_evidence" ]]; then
		data="$(IDENTITY_AVATAR_CHAIN="$chain" EXPECTED_REVISION="$EXPECTED_REVISION" \
			IDENTITY_AVATAR_OWNERSHIP_REVISION="$(identity_avatar_marker_value server_revision)" \
			IDENTITY_AVATAR_CLIENT_REVISION="$client_revision" IDENTITY_AVATAR_CLIENT_SHA="$client_sha" \
			IDENTITY_AVATAR_STABILITY_GENERATION="$stability_generation" \
			IDENTITY_AVATAR_STABILITY_SHA="$stability_sha" \
			IDENTITY_AVATAR_CLIENT_RETARGET_SHA="$client_retarget_sha" \
			IDENTITY_AVATAR_RUNTIME_RETARGET_SHA="$runtime_retarget_sha" \
			IDENTITY_AVATAR_WRITER_SHA="$writer_sha" IDENTITY_AVATAR_POLICY_SHA="$policy_sha" \
			IDENTITY_AVATAR_INVENTORY_SHA="$inventory_sha" IDENTITY_AVATAR_STATUS_SHA="$status_sha" \
			IDENTITY_AVATAR_REVOCATION_SHA="$revocation_sha" IDENTITY_AVATAR_SMOKE_SHA="$smoke_sha" \
			IDENTITY_AVATAR_BOUNDARY="$boundary" node <<'NODE'
const chain = JSON.parse(process.env.IDENTITY_AVATAR_CHAIN);
process.stdout.write(JSON.stringify({
  serverRevision: process.env.IDENTITY_AVATAR_OWNERSHIP_REVISION,
	  currentRuntimeRevision: process.env.EXPECTED_REVISION,
	  clientRevision: process.env.IDENTITY_AVATAR_CLIENT_REVISION,
	  runtimeStabilityGeneration: Number(process.env.IDENTITY_AVATAR_STABILITY_GENERATION),
	  runtimeStabilityEvidenceSha256: process.env.IDENTITY_AVATAR_STABILITY_SHA,
	  clientEvidenceSha256: process.env.IDENTITY_AVATAR_CLIENT_SHA,
	  clientRetargetEvidenceSha256: process.env.IDENTITY_AVATAR_CLIENT_RETARGET_SHA,
	  runtimeRetargetEvidenceSha256: process.env.IDENTITY_AVATAR_RUNTIME_RETARGET_SHA,
  writerFenceEvidenceSha256: process.env.IDENTITY_AVATAR_WRITER_SHA,
  storagePolicyEvidenceSha256: process.env.IDENTITY_AVATAR_POLICY_SHA,
  inventoryManifestSha256: process.env.IDENTITY_AVATAR_INVENTORY_SHA,
  statusManifestSha256: process.env.IDENTITY_AVATAR_STATUS_SHA,
  revocationEvidenceSha256: process.env.IDENTITY_AVATAR_REVOCATION_SHA,
  authenticatedSmokeEvidenceSha256: process.env.IDENTITY_AVATAR_SMOKE_SHA,
  firstHeartbeatSha256: chain.firstHeartbeatSha256,
  lastHeartbeatSha256: chain.lastHeartbeatSha256,
  heartbeatCount: chain.heartbeatCount,
  observationStartedAt: process.env.IDENTITY_AVATAR_BOUNDARY,
  observationEndedAt: chain.lastObservedAt,
  lastFrontendLogEvidenceSha256: chain.lastFrontendEvidenceSha256,
  lastFrontendLogEvidenceSignatureSha256: chain.lastFrontendEvidenceSignatureSha256,
  lastFrontendLogSequence: chain.lastFrontendSequence,
  frontendObservationStartedAt: chain.firstFrontendWindowStartedAt,
  frontendObservationEndedAt: chain.lastFrontendWindowEndedAt,
  lastBackendLogSetSha256: chain.lastBackendLogSetSha256,
  backendObservationEndedAt: chain.lastBackendWindowEndedAt,
  requiredSeconds: 604800,
  maximumGapSeconds: chain.maximumGapSeconds,
  continuityPassed: true,
  frontendLogContinuityPassed: true,
  backendLogContinuityPassed: true,
  legacyTrafficZeroPassed: true,
  bucketVersioningStablePassed: true,
  ownershipActivePassed: true,
  legacyRoutesFencedPassed: true,
  clientRevisionStablePassed: true,
  runtimeContainersStablePassed: true,
  verifiedAt: chain.lastObservedAt,
}));
NODE
)" || return 1
		identity_avatar_write_signed_json_evidence "$identity_avatar_soak_evidence" \
			identity-avatar-soak-complete "$data"
	fi
	identity_avatar_validate_soak_evidence "$client_revision" "$client_sha" "$client_retarget_sha" \
		"$runtime_retarget_sha" \
		"$writer_sha" "$policy_sha" "$inventory_sha" "$status_sha" "$revocation_sha" "$smoke_sha" "$chain" \
		"$stability_generation" "$stability_sha"
	soak_sha="$(identity_avatar_sha256 "$identity_avatar_soak_evidence")" || return 1
	soak_verified_at="$(identity_avatar_json_string_field "$identity_avatar_soak_evidence" verifiedAt)" || return 1
	identity_avatar_write_marker soak-complete "$initial_client_revision" "$writer_sha" "$policy_sha" \
		"$snapshot_sha" "$inventory_sha" "$migration_sha" "$status_sha" "$revocation_sha" \
		"$smoke_sha" "$client_sha" "$soak_sha" pending "$migration_ready_at" "$migrated_at" \
		"$client_switched_at" "$soak_verified_at"
	identity_avatar_validate_soak_timer_installation || return 1
	printf 'identity_avatar_soak=passed\n'
	printf 'identity_avatar_phase=soak-complete\n'
)

identity_avatar_runtime_stability_crypto_chain_self_test() (
	[[ $# -eq 2 && -d "$1" && ! -L "$1" && -f "$2" && ! -L "$2" &&
		"${CI:-}" == 'true' ]] || return 1
	local parent_root="$1" frontend_private_key="$2"
	local fixture_root="$parent_root/runtime-stability-real-crypto"
	local owner runtime client database_id client_binding candidate_tree runtime_contract
	local release_sha release_signature_sha release_tree_sha release_manifest_sha client_image
	local recorded_at observed_at process_started_at adopted_at runtimes frontend_binding
	local adoption_body adoption_signature adoption_body_sha adoption_signature_sha
	local writer policy smoke reference heartbeat terminal marker_payload
	local writer_sha policy_sha smoke_sha reference_sha heartbeat_sha terminal_sha chain
	mkdir -m 700 "$fixture_root" || return 1
	identity_avatar_artifact_root="$fixture_root/artifacts"
	identity_avatar_marker="$fixture_root/marker-v3.txt"
	identity_avatar_runtime_stability_current_body="$identity_avatar_artifact_root/runtime-stability-current-v1.json"
	identity_avatar_runtime_stability_current_signature="${identity_avatar_runtime_stability_current_body}.sig"
	identity_avatar_client_ready_public_root="$fixture_root/public"
	identity_avatar_runtime_stability_current_public_body="$identity_avatar_client_ready_public_root/runtime-stability-current-v1.json"
	identity_avatar_runtime_stability_current_public_signature="${identity_avatar_runtime_stability_current_public_body}.sig"
	identity_avatar_frontend_runtime_rebind_ready_body="$identity_avatar_artifact_root/frontend-runtime-rebind-ready-v1.json"
	identity_avatar_frontend_runtime_rebind_ready_signature="${identity_avatar_frontend_runtime_rebind_ready_body}.sig"
	identity_avatar_frontend_runtime_rebind_ready_public_body="$identity_avatar_client_ready_public_root/frontend-runtime-rebind-ready-v1.json"
	identity_avatar_frontend_runtime_rebind_ready_public_signature="${identity_avatar_frontend_runtime_rebind_ready_public_body}.sig"
	identity_avatar_cleanup_retarget_evidence="$identity_avatar_artifact_root/cleanup-retarget-v1.json"
	identity_avatar_cleanup_retarget_marker_archive="$identity_avatar_artifact_root/ownership-marker-soak-complete.txt"
	mkdir -m 700 "$identity_avatar_artifact_root" || return 1
	owner="$(printf '1%.0s' {1..40})"
	runtime="$owner"
	client="$(printf '3%.0s' {1..40})"
	database_id='123e4567-e89b-12d3-a456-426614174000'
	client_binding="$(printf '4%.0s' {1..64})"
	candidate_tree="$(printf '5%.0s' {1..64})"
	runtime_contract="$(printf '6%.0s' {1..64})"
	release_sha="$(printf '7%.0s' {1..64})"
	release_signature_sha="$(printf '8%.0s' {1..64})"
	release_tree_sha="$(printf '9%.0s' {1..64})"
	release_manifest_sha="$(printf 'a%.0s' {1..64})"
	client_image="sha256:$(printf 'b%.0s' {1..64})"
	recorded_at="$(node -e 'process.stdout.write(new Date(Math.floor((Date.now()-3600000)/1000)*1000).toISOString().replace(".000Z","Z"))')" || return 1
	observed_at="$recorded_at"
	process_started_at="$(node -e 'process.stdout.write(new Date(Date.now()-7200000).toISOString())')" || return 1
	adopted_at="$(node -e 'process.stdout.write(new Date(Date.now()-3700000).toISOString())' )" || return 1
	identity_avatar_configure_revision_paths "$owner" "$runtime" "$client" "$client" 0 "$(printf '0%.0s' {1..64})" || return 1
	mkdir -m 700 "$identity_avatar_runtime_stability_root" || return 1

	adoption_body="$(identity_avatar_runtime_stability_generation_path 0 frontend-image-adoption)" || return 1
	adoption_signature="$(identity_avatar_runtime_stability_generation_path 0 frontend-image-adoption-signature)" || return 1
	IDENTITY_AVATAR_FIXTURE_BODY="$adoption_body" IDENTITY_AVATAR_FIXTURE_SIGNATURE="$adoption_signature" \
		IDENTITY_AVATAR_FIXTURE_FRONTEND_KEY="$frontend_private_key" IDENTITY_AVATAR_FIXTURE_CLIENT="$client" \
		IDENTITY_AVATAR_FIXTURE_IMAGE="$client_image" IDENTITY_AVATAR_FIXTURE_RELEASE="$release_sha" \
		IDENTITY_AVATAR_FIXTURE_RELEASE_SIGNATURE="$release_signature_sha" \
		IDENTITY_AVATAR_FIXTURE_RELEASE_TREE="$release_tree_sha" \
		IDENTITY_AVATAR_FIXTURE_RELEASE_MANIFEST="$release_manifest_sha" \
		IDENTITY_AVATAR_FIXTURE_CANDIDATE_TREE="$candidate_tree" \
		IDENTITY_AVATAR_FIXTURE_ADOPTED_AT="$adopted_at" node <<'NODE'
const {sign}=require('node:crypto');const {readFileSync,writeFileSync}=require('node:fs');
const value={schemaVersion:1,kind:'identity-avatar-client-image-adoption-v1',
  clientRevision:process.env.IDENTITY_AVATAR_FIXTURE_CLIENT,
  clientImageId:process.env.IDENTITY_AVATAR_FIXTURE_IMAGE,
  releaseEvidenceSha256:process.env.IDENTITY_AVATAR_FIXTURE_RELEASE,
  releaseEvidenceSignatureSha256:process.env.IDENTITY_AVATAR_FIXTURE_RELEASE_SIGNATURE,
  releaseTreeSha256:process.env.IDENTITY_AVATAR_FIXTURE_RELEASE_TREE,
