    value.previousRuntimes.some((item, index) => JSON.stringify(Object.keys(item || {})) !== JSON.stringify(runtimeKeys) ||
      item.ociRevision !== value.previousRuntimeRevision || item.restartCount !== 0 ||
      item.service !== ['identity-api','identity-worker','identity-outbox-publisher','api','widgets-service'][index]) ||
    !Number.isSafeInteger(value.retargetSequence) || value.retargetSequence < 1 || value.retargetSequence > 4 ||
