	IDENTITY_AVATAR_MARKER_SOAK_RESET=true \
		identity_avatar_write_marker client-switched "$(identity_avatar_marker_value client_revision)" \
		"$(identity_avatar_marker_value writer_fence_evidence_sha256)" \
		"$(identity_avatar_marker_value storage_policy_evidence_sha256)" \
		"$(identity_avatar_marker_value uploads_snapshot_evidence_sha256)" \
		"$(identity_avatar_marker_value inventory_manifest_sha256)" \
		"$(identity_avatar_marker_value migration_manifest_sha256)" \
		"$(identity_avatar_marker_value status_manifest_sha256)" \
