	applied_sha="$(identity_avatar_sha256 "$applied")" || return 1
	if [[ "$mode" == 'bound' ]]; then
		[[ "$(identity_avatar_marker_value runtime_revision)" == "$candidate" &&
			"$(identity_avatar_marker_value runtime_retarget_evidence_sha256)" == "$applied_sha" ]] || return 1
	else
		[[ "$(identity_avatar_marker_value runtime_revision)" == "$previous" &&
			"$(identity_avatar_marker_value runtime_retarget_evidence_sha256)" == "$stage_sha" ]] || return 1
		chain="$(identity_avatar_validate_runtime_stability_chain reconcile)" || return 1
		generation="$(IDENTITY_AVATAR_APPLIED_CHAIN="$chain" node -e '
const value=JSON.parse(process.env.IDENTITY_AVATAR_APPLIED_CHAIN);
if(!Number.isSafeInteger(value.generation))process.exit(1);process.stdout.write(String(value.generation));')" || return 1
		mutation_start="$(identity_avatar_runtime_stability_generation_path "$generation" mutation-start)" || return 1
		identity_avatar_verify_detached_lifecycle_evidence "$mutation_start" \
			identity-avatar-runtime-stability-mutation-start || return 1
		IDENTITY_AVATAR_APPLIED_CHAIN="$chain" IDENTITY_AVATAR_APPLIED_CANDIDATE="$candidate" \
			IDENTITY_AVATAR_APPLIED_STAGE_SHA="$stage_sha" IDENTITY_AVATAR_APPLIED_SHA="$applied_sha" \
			IDENTITY_AVATAR_APPLIED_FILE="$applied" IDENTITY_AVATAR_APPLIED_STAGE_FILE="$stage" \
			IDENTITY_AVATAR_APPLIED_MUTATION_FILE="$mutation_start" node -e '
const value=JSON.parse(process.env.IDENTITY_AVATAR_APPLIED_CHAIN),applied=require(process.env.IDENTITY_AVATAR_APPLIED_FILE);
const stage=require(process.env.IDENTITY_AVATAR_APPLIED_STAGE_FILE),mutation=require(process.env.IDENTITY_AVATAR_APPLIED_MUTATION_FILE);
const prepared=value.prepared,terminal=value.terminal;
const mutationKeys=["version","kind","ownershipRevision","runtimeRevision","generation","transitionReason",
 "previousRuntimeStabilityEvidenceSha256","preparedEvidenceSha256","previousRuntimes","liveRuntimesBeforeMutation",
 "preparedAt","expiresAt","mutationStartedAt","signature"];
const mutationExact=JSON.stringify(Object.keys(mutation||{}))===JSON.stringify(mutationKeys)&&mutation.version===1&&
 mutation.kind==="identity-avatar-runtime-stability-mutation-start"&&mutation.generation===value.generation&&
 mutation.transitionReason==="backend-code-retarget"&&mutation.runtimeRevision===process.env.IDENTITY_AVATAR_APPLIED_CANDIDATE&&
 mutation.preparedEvidenceSha256===value.preparedSha256&&mutation.preparedAt===prepared?.preparedAt&&
 mutation.expiresAt===prepared?.expiresAt&&JSON.stringify(mutation.previousRuntimes)===JSON.stringify(prepared?.previousRuntimes)&&
 JSON.stringify(mutation.liveRuntimesBeforeMutation)===JSON.stringify(prepared?.previousRuntimes)&&
 Date.parse(applied.appliedAt)>=Date.parse(mutation.mutationStartedAt);
const pending=value.tailState==="prepared"&&prepared?.transitionReason==="backend-code-retarget"&&
 prepared.runtimeRevision===process.env.IDENTITY_AVATAR_APPLIED_CANDIDATE&&
 prepared.runtimeRetargetEvidenceSha256===process.env.IDENTITY_AVATAR_APPLIED_STAGE_SHA&&
 prepared.candidateTreeSha256===applied.candidateTreeSha256&&
 prepared.runtimeContractSha256===applied.runtimeContractSha256;
const terminalAhead=value.tailState==="applied"&&terminal?.transitionReason==="backend-code-retarget"&&
 terminal.runtimeRevision===process.env.IDENTITY_AVATAR_APPLIED_CANDIDATE&&
 terminal.runtimeRetargetEvidenceSha256===process.env.IDENTITY_AVATAR_APPLIED_SHA&&
 terminal.preparedEvidenceSha256===value.preparedSha256&&terminal.candidateTreeSha256===applied.candidateTreeSha256&&
 terminal.runtimeContractSha256===applied.runtimeContractSha256&&
 terminal.writerFenceEvidenceSha256===applied.writerFenceEvidenceSha256&&
 terminal.storagePolicyEvidenceSha256===applied.storagePolicyEvidenceSha256&&
 terminal.authenticatedSmokeEvidenceSha256===applied.authenticatedSmokeEvidenceSha256&&
 terminal.initialClientRevision===applied.initialClientRevision&&terminal.currentClientRevision===applied.currentClientRevision&&
 terminal.identityDatabaseId===applied.identityDatabaseId&&
 terminal.clientRetargetEvidenceSha256===applied.clientRetargetEvidenceSha256&&
 JSON.stringify(terminal.previousRuntimes)===JSON.stringify(applied.previousRuntimes)&&
 JSON.stringify(terminal.currentRuntimes)===JSON.stringify(applied.currentRuntimes)&&
